import csv, json

users = []
with open('users.csv', newline='') as f:
    for row in csv.DictReader(f):
        users.append(row)

ids = {u['id'] for u in users}
totals = {u['id']: 0.0 for u in users}

with open('orders.jsonl') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        o = json.loads(line)
        uid = str(o.get('user_id'))
        if uid in ids and o.get('status') == 'paid':
            totals[uid] += float(o.get('total', 0))

report = [{'user': u['name'], 'country': u['country'], 'paid_total': round(totals[u['id']], 2)} for u in users]
report.sort(key=lambda r: (-r['paid_total'], r['user']))

with open('report.json', 'w') as f:
    json.dump(report, f, indent=2)
